#include <bits/stdc++.h>
using namespace std;
const int MOD=998244353;
bool check(int n,int x,int l,int s,vector<int>&v)
{
    int pos;
    if(s==0)
    pos=l+1;
    else
    pos=n-x+l+1;
    for(int i:v)
    {
        bool ok=false;
        if(pos<=i)
        {
            int c=x-min(n-i,x-1-l);
            if(c==(i+1)/2)
            ok=true;
            
        }
        if(pos>=i)
        {
            int c=x-min(i-1,l);
            if(c==(n-i+2)/2)
            ok=true;
        }
        if(!ok)
        return false;
    }
    return true;
}
int main() {
	// your code goes here
int t;
cin>>t;
while(t--)
{
    int n;
    cin>>n;
    vector<vector<int>>v(n+1);
    for(int i=1;i<=n;i++)
    {
        int x;
        cin>>x;
        v[x].push_back(i);
    }
    vector<int>dp(n+1,0);
    dp[0]=1;
    for(int x=1;x<=n;x++)
    
    {
        vector<int>ndp(n+1,0);
        for(int l=0;l<x;l++)
        {
            if(dp[l]==0)
            continue;
            if(check(n,x,l,0,v[x]))
            {
                ndp[l+1]+=dp[l];
                if(ndp[l+1]>=MOD)
                ndp[l+1]-=MOD;
            }
            if(x<n && check(n,x,l,1,v[x]))
            {
                ndp[l]+=dp[l];
                if(ndp[l]>=MOD)
                ndp[l]-=MOD;
            }
        }
        dp=ndp;
    }
    int ans=0;
    for(int i=0;i<=n;i++)
    {
        ans+=dp[i];
        if(ans>=MOD)
        ans-=MOD;
    }
    cout<<ans<<"\n";
}
return 0;
}
